/**
 * <p>Boolean factory that avoids creating new Boolean objecs all the time.</p>

impl_B:
public static boolean isFalse(Boolean bool) {
        if (bool == null) {
            return false;
        }
        return bool.booleanValue() ? false : true;
    }
